import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type AnimatedButtonCTAProps = Record<string, any>;

const AnimatedButtonCTA: React.FC<AnimatedButtonCTAProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 5,
  buttonText = "BOOK NOW",
  buttonColor = "#FF3366",
  buttonTextColor = "#FFFFFF",
  subtextItems = [
    "Blood Work Analysis",
    "Personalised Nutrition Plan",
    "Sustainable Weight Loss",
  ],
  subtextColor = "#E0E0E0",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive calculations
  const s = Math.min(width, height);
  const isPortrait = height > width;

  // --- Animation Logic ---

  // Button Entrance Animation
  const buttonEntrance = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 90 },
    durationInFrames: 35,
  });

  // Continuous subtle pulse effect for the button
  // Starts after the initial entrance settles
  const pulsePhase = Math.max(0, frame - 30);
  const pulseScale = interpolate(
    Math.cos(pulsePhase * 0.1),
    [-1, 1],
    [1, 1.04],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const finalButtonScale = buttonEntrance * pulseScale;

  const buttonY = interpolate(buttonEntrance, [0, 1], [height * 0.1, 0]);
  const buttonOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        padding: isPortrait ? "10%" : "5%",
      }}
    >
      {/* Main CTA Button */}
      <div
        style={{
          transform: `translateY(${buttonY}px) scale(${finalButtonScale})`,
          opacity: buttonOpacity,
          backgroundColor: buttonColor,
          color: buttonTextColor,
          padding: `${s * 0.05}px ${s * 0.12}px`,
          borderRadius: s * 0.1,
          fontSize: s * 0.08,
          fontWeight: 800,
          letterSpacing: "0.02em",
          boxShadow: `0 ${s * 0.02}px ${s * 0.06}px rgba(0,0,0,0.4), 0 0 ${s * 0.05}px ${buttonColor}40`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          marginBottom: s * 0.08,
          transition: "none",
          textTransform: "uppercase",
          zIndex: 10,
        }}
      >
        {buttonText}
      </div>

      {/* Subtext Features List */}
      <div
        style={{
          display: "flex",
          flexDirection: "column", // Optimized for vertical stacking on 9:16
          gap: isPortrait ? s * 0.04 : s * 0.03,
          alignItems: isPortrait ? "flex-start" : "center",
          justifyContent: "center",
          width: isPortrait ? "85%" : "auto",
        }}
      >
        {subtextItems.map((item, index) => {
          // Staggered entrance for each list item
          const delay = 25 + index * 8;
          const itemProgress = spring({
            frame: frame - delay,
            fps,
            config: { damping: 14, stiffness: 80 },
          });

          const itemY = interpolate(itemProgress, [0, 1], [30, 0]);
          const itemOpacity = interpolate(
            frame - delay,
            [0, 12],
            [0, 1],
            { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
          );

          return (
            <div
              key={index}
              style={{
                display: "flex",
                alignItems: "center",
                gap: s * 0.03,
                transform: `translateY(${itemY}px)`,
                opacity: itemOpacity,
                transition: "none",
                width: "100%",
                justifyContent: isPortrait ? "flex-start" : "center",
              }}
            >
              {/* Animated Bullet Point */}
              <div
                style={{
                  width: s * 0.02,
                  height: s * 0.02,
                  borderRadius: "50%",
                  backgroundColor: buttonColor,
                  opacity: itemProgress,
                  transform: `scale(${itemProgress})`,
                  flexShrink: 0,
                  boxShadow: `0 0 ${s * 0.01}px ${buttonColor}80`,
                }}
              />
              
              {/* Text Content */}
              <span
                style={{
                  color: subtextColor,
                  fontSize: s * 0.045,
                  fontWeight: 500,
                  lineHeight: 1.3,
                  textShadow: `0 2px 4px rgba(0,0,0,0.5)`,
                }}
              >
                {item}
              </span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default AnimatedButtonCTA;